      "hardGatesPass": true,
      "objections": []
    },
    {
      "candidateId": "candidate-2",
      "strategy": "Streamlined 5-component layout focusing solely on financial points preservation: REENGAGEMENT_BANNER, POINTS_BALANCE, EXPIRING_POINTS_ALERT, QUICK_REDEEM_CARD, and TANGIBLE_VALUE_CARD. Excludes instant flash rewards to test sober financial utility.",
