      "objections": [
        {"agent": "Personalization Synthesiser", "issue": "Omitting INSTANT_REWARD_POPUP and QUICK_WIN_CARD undershoots the rich component requirement (7-9 recommended) and ignores high-confidence behavioural preference for flash rewards."}
